//! battery.resource's functions: the board's battery - whether a cell is
//! there, its voltage and its charge, external power and charging where
//! the board can tell - and who is told when that changes. A resource: no
//! Open or Close, its first function in the first slot. The base comes
//! from OpenResource("battery.resource").
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/battery_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const exec = @import("../libs/exec/exec.zig");
const battery = @import("../resources/battery.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "battery.resource";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const ReadBattery = libraries.lvo(0);
    pub const AddBatteryNotify = libraries.lvo(1);
    pub const RemBatteryNotify = libraries.lvo(2);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const ReadBattery = *const fn (*BatteryBase, *battery.BatteryState) callconv(.c) bool;
    pub const AddBatteryNotify = *const fn (*BatteryBase, *exec.Task, u32) callconv(.c) ?*battery.BatteryNotify;
    pub const RemBatteryNotify = *const fn (*BatteryBase, ?*battery.BatteryNotify) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const BatteryBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *BatteryBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// The battery as last measured, into `state`. False if the board has no
    /// battery whose voltage it can measure; `state` then says what it can
    /// tell all the same.
    pub fn ReadBattery(self: *BatteryBase, state: *battery.BatteryState) bool {
        return libraries.call(self, LVO.ReadBattery, Fn.ReadBattery, .{state});
    }

    /// `signals` sent to `task` whenever a cell comes or goes, external power
    /// comes or goes, charging starts or ends, or the charge passes
    /// BATTERY_LOW or BATTERY_CRITICAL; null without memory.
    pub fn AddBatteryNotify(self: *BatteryBase, task: *exec.Task, signals: u32) ?*battery.BatteryNotify {
        return libraries.call(self, LVO.AddBatteryNotify, Fn.AddBatteryNotify, .{ task, signals });
    }

    /// No more of that.
    pub fn RemBatteryNotify(self: *BatteryBase, notify: ?*battery.BatteryNotify) void {
        return libraries.call(self, LVO.RemBatteryNotify, Fn.RemBatteryNotify, .{notify});
    }
};
